 static Dictionary<string,object> ReadInput(Stream s,Dictionary<string,string> headers){
  string type,origin,host,len;int n;
  if(!headers.TryGetValue("Content-Type",out type)||!type.StartsWith("application/json",StringComparison.OrdinalIgnoreCase))throw new Exception("JSONで送信してください。");
  if(headers.TryGetValue("Origin",out origin)){Uri uri;if(!Uri.TryCreate(origin,UriKind.Absolute,out uri)||!headers.TryGetValue("Host",out host)||uri.Authority!=host||uri.Scheme!="http")throw new Exception("別サイトからのリクエストは許可されていません。");}
  if(!headers.TryGetValue("Content-Length",out len)||!int.TryParse(len,out n)||n<0||n>2097152)throw new Exception("データが大きすぎます。");byte[] body=new byte[n];int read=0;while(read<n){int k=s.Read(body,read,n-read);if(k==0)throw new IOException();read+=k;}
  return new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(Encoding.UTF8.GetString(body));
 }
